<?php
require_once __DIR__.'/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Kalender';$activePage='kalender.php';$ym=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$ym))$ym=date('Y-m');$first=new DateTimeImmutable($ym.'-01');$days=(int)$first->format('t');$start=$first->modify('-'.((int)$first->format('N')-1).' days');$end=$start->modify('+41 days');$from=$start->format('Y-m-d');$to=$end->format('Y-m-d');
$events=[];$add=function(string $date,string $type,string $title,string $amount)use(&$events){$events[$date][]=compact('type','title','amount');};$st=$pdo->prepare('SELECT type,category,description,amount,transaction_date FROM transactions WHERE user_id=? AND transaction_date BETWEEN ? AND ?');$st->execute([$uid,$from,$to]);foreach($st as $r)$add($r['transaction_date'],$r['type'],$r['description']?:$r['category'],formatRupiah($r['amount']));$st=$pdo->prepare('SELECT name,amount,due_date FROM bills WHERE user_id=? AND due_date BETWEEN ? AND ?');$st->execute([$uid,$from,$to]);foreach($st as $r)$add($r['due_date'],'bill',$r['name'],formatRupiah($r['amount']));$st=$pdo->prepare('SELECT name,total_amount,due_date FROM debts WHERE user_id=? AND status<>"Lunas" AND due_date BETWEEN ? AND ?');$st->execute([$uid,$from,$to]);foreach($st as $r)$add($r['due_date'],'debt',$r['name'],formatRupiah($r['total_amount']));$st=$pdo->prepare('SELECT name,total_amount,due_date FROM receivables WHERE user_id=? AND status<>"Lunas" AND due_date BETWEEN ? AND ?');$st->execute([$uid,$from,$to]);foreach($st as $r)$add($r['due_date'],'receivable',$r['name'],formatRupiah($r['total_amount']));$selected=(string)($_GET['date']??'');$selectedEvents=$events[$selected]??[];$user=currentUser($pdo);require __DIR__.'/includes/header.php';$monthName=$first->format('F Y');
?>
<div class="page-heading"><div><p class="eyebrow">Ritme keuangan</p><h1>Kalender Keuangan</h1><p>Lihat pemasukan, pengeluaran, tagihan, utang, dan piutang berdasarkan tanggal.</p></div></div>
<section class="card"><div class="calendar-head"><a class="btn btn-ghost btn-sm" href="?month=<?=$first->modify('-1 month')->format('Y-m')?>"><i data-lucide="chevron-left"></i></a><div class="calendar-title"><?=e($monthName)?></div><a class="btn btn-ghost btn-sm" href="?month=<?=$first->modify('+1 month')->format('Y-m')?>"><i data-lucide="chevron-right"></i></a></div><div class="calendar-grid"><?php foreach(['Sen','Sel','Rab','Kam','Jum','Sab','Min'] as $day):?><div class="calendar-weekday"><?=$day?></div><?php endforeach;?><?php for($i=0;$i<42;$i++):$date=$start->modify("+{$i} days");$ds=$date->format('Y-m-d');$inside=$date->format('Y-m')===$ym;$dayEvents=$events[$ds]??[];?><a class="calendar-day <?=$inside?'':'muted'?> <?=$ds===date('Y-m-d')?'today':''?>" href="?month=<?=$ym?>&date=<?=$ds?>"><strong><?=$date->format('j')?></strong><div class="markers"><?php foreach(array_slice($dayEvents,0,8) as $ev):?><span class="marker <?=e($ev['type'])?>" title="<?=e($ev['title'])?>"></span><?php endforeach;?></div></a><?php endfor;?></div><div class="calendar-legend"><span><i class="marker income"></i>Pemasukan</span><span><i class="marker expense"></i>Pengeluaran</span><span><i class="marker bill"></i>Tagihan</span><span><i class="marker debt"></i>Utang</span><span><i class="marker receivable"></i>Piutang</span></div></section>
<?php if($selected):?><section class="card" style="margin-top:18px"><div class="card-header"><div><h2 class="card-title">Aktivitas <?=e(date('d/m/Y',strtotime($selected)))?></h2><p class="card-subtitle">Detail aktivitas pada tanggal terpilih.</p></div><a class="btn btn-ghost btn-sm" href="?month=<?=$ym?>">Tutup</a></div><?php if(!$selectedEvents):?><div class="empty-state">Tidak ada aktivitas keuangan pada tanggal ini.</div><?php else:?><div class="list"><?php foreach($selectedEvents as $ev):?><div class="transaction-row"><div class="type-dot <?=e($ev['type'])?>"><i data-lucide="<?=$ev['type']==='income'?'arrow-down-left':($ev['type']==='expense'?'arrow-up-right':'calendar-clock')?>"></i></div><div class="row-main"><strong><?=e($ev['title'])?></strong><small><?=e(ucfirst($ev['type']))?></small></div><div class="row-amount"><?=e($ev['amount'])?></div></div><?php endforeach;?></div><?php endif;?></section><?php endif;?>
